    /// <summary>The text of <paramref name="command"/>, Polish for "pl", else English; its name when unknown.</summary>
    public static string Of(string command, string languageCode) =>
        Texts.TryGetValue(command, out var text) ? languageCode == "pl" ? text.Polish : text.English : command;

    /// <summary>The commands there are texts for.</summary>
    public static IEnumerable<string> Commands => Texts.Keys;
